  return [echoTool];
}

export async function callTool(name, args = {}) {
  if (name !== 'echo') {
    const error = new Error(`Unknown tool: ${name}`);
    error.code = -32601;
    throw error;
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    const error = new Error('Invalid arguments: expected an object');
    error.code = -32602;
    throw error;
  }

  const schema = echoTool.inputSchema;
  const provided = Object.keys(args);

  for (const key of provided) {
    if (!(key in schema.properties)) {
      const error = new Error(`Invalid argument: ${key}`);
      error.code = -32602;
      throw error;
    }
  }

  for (const field of schema.required) {
    if (!(field in args)) {
      const error = new Error(`Missing required argument: ${field}`);
      error.code = -32602;
      throw error;
    }
  }

  const { message } = args;
  if (typeof message !== 'string') {
    const error = new Error('Invalid argument: message must be a string');
    error.code = -32602;
    throw error;
  }

  return {
    content: [{ type: 'text', text: message }]
  };
}

